\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs20 Kanonikerstift {\field{\*\fldinst HYPERLINK "hida://bezsoz[1].4600/?u"}{\fldrslt \plain \f0\fs20\chcbpat17 St. Stephan in Mainz}}\plain \f0\fs20  (gestempeltes \plain \f0\i\fs20 SS\plain \f0\fs20  auf dem Einband), sp\u228 \'e4ter Geschenk an das Augustinerkloster. 1r besch\u228 \'e4digter Schenkungsvermerk an die {\field{\*\fldinst HYPERLINK "hida://bezsoz[2].4600/?u"}{\fldrslt \plain \f0\fs20\chcbpat17 Augustinereremiten Mainz}}\plain \f0\fs20 : {\field{\*\fldinst HYPERLINK "hida://5650[0].5686/?u"}{\fldrslt \plain \f0\i\fs20\chcbpat17 Ex liberalissima donatione Insignis Ecclesiae Collegiatae ad Sanctum Stephanum et Capituli p. l. Decani Christoph Nebel Episcopalis Caplani suffragani Moguntinae Schola\u223 \'dftie, Franz Erwein Von Nitschke, Cantor Joan Philipp. Anton Sundermichler(?), Fabricae Magister Joan. Damogoz}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5686/?u"}{\fldrslt \plain \f0\fs20\chcbpat17 (?)}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5686/?u"}{\fldrslt \plain \f0\i\fs20\chcbpat17 , Confessor frater Nicolas Schlender supp. Annumeror Bibliotthecae fratrum Eremitarum Sancti pp}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5686/?u"}{\fldrslt \plain \f0\fs20\chcbpat17 (?)}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5686/?u"}{\fldrslt \plain \f0\i\fs20\chcbpat17  Augustini Moguntiae 1753}}\plain \f0\fs20 . Zuerst 1962 in der Buchbindereii Schoy in Essen restauriert.}

